#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

static char ibuf[1 << 16];
static int ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return (unsigned char)ibuf[ipos++];
}
static inline int readInt() {
    int c = gc();
    while (c != -1 && c != '-' && (c < '0' || c > '9')) c = gc();
    int neg = 0;
    if (c == '-') { neg = 1; c = gc(); }
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

static int A[1005][1005];
static int heights[1005], leftE[1005], rightE[1005];
static int stk[1005];

int main() {
    int L = readInt(), C = readInt();
    for (int i = 0; i < L; i++)
        for (int j = 0; j < C; j++)
            A[i][j] = readInt();

    // A matrix (submatrix) is super-legal iff for every rectangle of adjacent 2x2
    // blocks inside it, A[i][j] + A[i+1][j+1] <= A[i][j+1] + A[i+1][j].
    // Mark "bad" cells in a grid of size (L-1) x (C-1). A submatrix with >=2 rows/cols
    // is super-legal iff the corresponding rectangle in the bad grid is all-zero,
    // and its area is (h+1)*(w+1). Single row/column submatrices give max(L, C).
    long long ans = max(L, C);
    int W = C - 1;
    for (int c = 0; c < W; c++) heights[c] = 0;

    for (int r = 0; r + 1 < L; r++) {
        for (int c = 0; c < W; c++) {
            int a = A[r][c] + A[r + 1][c + 1];
            int b = A[r][c + 1] + A[r + 1][c];
            heights[c] = (a > b) ? 0 : heights[c] + 1;
        }
        int top = 0;
        for (int c = 0; c < W; c++) {
            while (top > 0 && heights[stk[top - 1]] >= heights[c]) top--;
            leftE[c] = (top > 0) ? stk[top - 1] + 1 : 0;
            stk[top++] = c;
        }
        top = 0;
        for (int c = W - 1; c >= 0; c--) {
            while (top > 0 && heights[stk[top - 1]] >= heights[c]) top--;
            rightE[c] = (top > 0) ? stk[top - 1] - 1 : W - 1;
            stk[top++] = c;
        }
        for (int c = 0; c < W; c++) {
            long long area = (long long)(heights[c] + 1) * (long long)(rightE[c] - leftE[c] + 2);
            if (area > ans) ans = area;
        }
    }

    printf("%lld\n", ans);
    return 0;
}
